mapper.select:
SELECT s.id, s.movie_id, s.hall_id, s.cinema_id, s.start_time, s.price, s.create_time, s.update_time, m.title AS movie_title, h.name AS hall_name FROM t_screening s LEFT JOIN t_movie m ON s.movie_id = m.id LEFT JOIN t_hall h ON s.hall_id = h.id WHERE s.cinema_id = #{cinemaId}
AND s.movie_id = #{movieId}
ORDER BY s.start_time DESC
